<script setup lang="ts">
import {ref} from 'vue'
import {onLoad} from '@dcloudio/uni-app'
import PageShell from '../../../components/PageShell.vue'
import AppIcon from '../../../components/AppIcon.vue'
import StatePanel from '../../../components/StatePanel.vue'
import StatusBadge from '../../../components/StatusBadge.vue'
import {reportsApi} from '../../../api/reports'
import {doctorApi} from '../../../api/doctor'
import {usePageData} from '../../../utils/usePageData'
import {previewFile} from '../../../utils/upload'
import {toast,errorText} from '../../../utils/format'
import type {Report} from '../../../types'
const data=ref<Report>(),id=ref(''),active=ref(0),page=ref(0),note=ref(''),values=ref<Record<string,string>>({}),confirmed=ref<string[]>([]),busy=ref(false)
onLoad(q=>id.value=q?.id||'')
const {loading,error,load}=usePageData('doctor',async()=>{if(!id.value)throw new Error('缺少报告编号');data.value=await reportsApi.detail(id.value);values.value=Object.fromEntries(data.value.fields.map(f=>[f.key,f.value]));note.value=data.value.reviewNote||'';confirmed.value=[]})
function confirm(key:string){if(data.value?.status!=='pending')return;confirmed.value=confirmed.value.includes(key)?confirmed.value.filter(k=>k!==key):[...confirmed.value,key]}
async function decide(approve:boolean){
 if(!data.value||busy.value||data.value.status!=='pending')return
 if(!note.value.trim()){toast('请填写审核备注');return}
 if(approve&&(!data.value.fields.length||data.value.fields.some(f=>f.needsConfirm&&!confirmed.value.includes(f.key)))){toast('请逐项核对并确认需人工复核的字段');active.value=1;return}
 if(approve&&data.value.fields.some(f=>!values.value[f.key]?.trim())){toast('请填写完整的核对结果');return}
 const report=data.value
 uni.showModal({title:approve?'确认审核通过':'退回重新处理',content:approve?'将提交字段核对结果及审核意见，原始报告与正式结论保持原样。':'将向报告提交人反馈您的备注，请写明需要补充或修正的内容。',success:async r=>{
  if(!r.confirm)return
  busy.value=true
  try{const payload={note:note.value.trim(),corrections:report.fields.filter(f=>values.value[f.key]!==f.value).map(f=>({key:f.key,value:values.value[f.key]})),confirmedFields:confirmed.value};data.value=await (approve?doctorApi.approve(id.value,payload):doctorApi.reject(id.value,payload));toast(approve?'审核结果已提交':'报告已退回')}catch(e){toast(errorText(e))}finally{busy.value=false}
 }})
}
</script>
<template><PageShell title="报告审核详情"><view class="content"><StatePanel :loading="loading" :error="error" @retry="load"/><template v-if="data"><view class="card reviewer-person"><image class="avatar" src="/static/miner.png"/><view class="grow"><text class="reviewer-name">{{data.workerName}}</text><text class="help">{{data.employeeNo}} · {{data.date}}</text></view><StatusBadge :status="data.status"/></view><view class="tabs detail-tabs"><view v-for="(t,i) in ['报告原件','提取结果','AI辅助分析']" :key="t" :class="{active:active===i}" @tap="active=i">{{t}}</view></view><view v-if="active===0" class="card"><view class="section-head"><text class="section-title">原始体检报告</text><text class="help">{{page+1}} / {{data.files.length}}</text></view><template v-if="data.files[page]"><view class="original-preview" @tap="previewFile(data.files[page].url,data.files[page].type).catch(e=>toast(errorText(e)))"><image v-if="data.files[page].type==='image'" :src="data.files[page].url" mode="widthFix"/><view v-else class="pdf-preview"><AppIcon name="file-text" :size="60"/><text>{{data.files[page].name}}</text><text class="green-text">点击打开 PDF 原件</text></view><view class="expand"><AppIcon name="maximize" color="white" :size="19"/></view></view><text class="source" style="display:block">{{data.files[page].name}} · 点击放大查看</text><view class="pagination"><button class="btn btn-soft small" :disabled="page===0" @tap="page--">上一页</button><text>{{page+1}} / {{data.files.length}}</text><button class="btn btn-soft small" :disabled="page>=data.files.length-1" @tap="page++">下一页</button></view></template><view class="divider"/><text class="bold">体检机构正式结论（只读）</text><text class="paragraph" style="display:block;margin-top:16rpx">{{data.conclusion}}</text></view><view v-if="active===1" class="card"><text class="section-title">关键结果核对</text><view class="help" style="margin-top:10rpx">以下为后端 OCR 提取结果，请与原件逐项核对</view><view class="info-line"><text>体检日期</text><text>{{data.date}}</text></view><view class="info-line"><text>体检机构</text><text>{{data.institution}}</text></view><view v-for="f in data.fields" :key="f.key" class="ocr-field"><view class="between"><text class="bold">{{f.label}}</text><text class="confidence" :class="{uncertain:f.needsConfirm}">识别置信度 {{Math.round(f.confidence*100)}}%</text></view><view class="ocr-input"><input v-model="values[f.key]" :disabled="data.status!=='pending'||busy" maxlength="150"/><text class="help">{{f.unit}}</text></view><text v-if="f.sourceValue" class="help">原提取值：{{f.sourceValue}}</text><view v-if="f.needsConfirm" class="manual-confirm" @tap="confirm(f.key)"><view class="check-box" :class="{on:confirmed.includes(f.key)}"><AppIcon v-if="confirmed.includes(f.key)" name="check" color="white" :size="12"/></view><text>{{data.status==='pending'?'需人工确认 · 我已对照原件核实':'提取时标记为需人工确认'}}</text></view></view><view v-if="!data.fields.length" class="alert" style="margin-top:25rpx">暂无提取字段，请等待后端处理或退回重新处理。</view><view class="hint" style="margin-top:25rpx">修正仅针对提取数据，提交到后端保留修正与审计记录，不改写体检机构原始结论。</view></view><view v-if="active===2" class="card"><view class="flex gap"><AppIcon name="bot" :size="28"/><text class="section-title">AI辅助分析</text></view><text class="paragraph" style="display:block;margin-top:25rpx">{{data.analysis}}</text><view class="hint" style="margin-top:26rpx">AI分析仅供医生参考，不作为正式诊断或上岗资格决定。</view></view><view class="card"><text class="section-title">{{data.status==='pending'?'审核备注':'已提交审核意见'}}</text><textarea v-model="note" class="note-input" :disabled="data.status!=='pending'||busy" :maxlength="1000" placeholder="请填写核对情况、修正说明或退回原因…"/><view class="help">{{note.length}} / 1000</view></view><view v-if="data.status==='pending'" class="two-actions"><button class="btn btn-outline" :disabled="busy" @tap="decide(false)">退回修改</button><button class="btn" :loading="busy" :disabled="busy" @tap="decide(true)">审核通过</button></view></template></view></PageShell></template>
<style scoped>.reviewer-person{display:flex;align-items:center;gap:20rpx}.reviewer-person .avatar{height:86rpx;width:86rpx}.reviewer-name{display:block;font-size:32rpx;font-weight:650}.detail-tabs{justify-content:space-around}.original-preview{position:relative;background:#f0f2ef;padding:14rpx;border-radius:17rpx;overflow:hidden;margin-top:25rpx;min-height:280rpx}.original-preview>image{width:100%}.expand{position:absolute;right:24rpx;top:24rpx;padding:12rpx;background:#244d3ac0;border-radius:12rpx}.pagination{display:flex;align-items:center;justify-content:space-between;gap:20rpx;margin-top:25rpx;font-size:24rpx;color:#8da395}.pdf-preview{display:flex;flex-direction:column;align-items:center;gap:26rpx;padding:50rpx 10rpx;font-size:25rpx}.ocr-field{padding:25rpx 0;border-bottom:1px solid #eef2ee;font-size:27rpx}.confidence{color:#7da68b;font-size:20rpx}.confidence.uncertain{color:#b58434}.ocr-input{display:flex;align-items:center;gap:15rpx;margin-top:15rpx}.ocr-input input{height:82rpx;background:#f6f9f6;border:1px solid #e7eee7;border-radius:12rpx;padding:18rpx;flex:1}.manual-confirm{display:flex;align-items:center;gap:13rpx;margin-top:15rpx;color:#b38232;font-size:22rpx}.check-box{height:29rpx;width:29rpx;border:1px solid #c3bd97;border-radius:6rpx;display:flex;align-items:center;justify-content:center}.check-box.on{background:#00985b;border-color:#00985b}.note-input{margin-top:20rpx;background:#f6f9f6;border:1px solid #edf1ec;border-radius:16rpx;padding:22rpx;height:210rpx;font-size:25rpx}</style>
